package com.xuanji.app.domain.divination

import kotlin.random.Random

/**
 * 雷诺曼卡牌（Lenormand，36 张）：抽 3 张对应 过去 / 现在 / 未来。
 * 牌义为通用释义，离线随机抽牌，仅供文化娱乐参考。
 */
object Lenormand {

    data class Card(
        val num: Int,
        val nameCn: String,
        val nameEn: String,
        val meaning: String,
        val verdict: String
    )

    data class Draw(
        val position: String,
        val card: Card
    )

    data class LenormandResult(
        val draws: List<Draw>,
        val verdict: String
    )

