    fun draw(random: Random = Random.Default): LenormandResult {
        val idxs = DECK.indices.shuffled(random).take(3)
        val positions = listOf("过去", "现在", "未来")
        val draws = idxs.mapIndexed { i, idx -> Draw(positions[i], DECK[idx]) }
        return LenormandResult(draws, buildVerdict(draws))
    }

    /** 由过去/现在/未来三张牌合成六维总览 */
    private fun buildVerdict(draws: List<Draw>): String {
        val past = draws.getOrNull(0)?.card?.nameCn ?: ""
        val now = draws.getOrNull(1)?.card?.nameCn ?: ""
        val future = draws.getOrNull(2)?.card?.nameCn ?: ""
        return buildString {
            append("总评：三牌勾勒出「过去 $past、现在 $now、未来 $future」的脉络，过去埋下的因正在此刻显影，并指向未来的走向，整体宜顺势而为。\n")
            append("事业：事业看「现在」的走向，$now 的意象即为当下职场的核心，把握好这一张，事业便有抓手。\n")
            append("财运：财运沿「过去」的轨迹运行，$past 留下的积累与缺口，将直接决定接下来的收支基调。\n")
            append("感情：感情望向「未来」的图景，$future 的提示即是经营关系时最该留心的方向。\n")
            append("健康：健康是贯穿三牌的基础盘，无论牌面吉凶，规律的作息与情绪管理都是最稳的底牌。\n")
            append("建议：把三张牌的讯息合而观之——过去不追悔、现在不敷衍、未来不空想，按部就班自见分晓。")
        }
    }
